					arg:InitEsp(tbl15)
					arg.Cache[player] = tbl15

					tbl15.BindHealth = ({ BindHealth = function(humanoid)
						if tbl15["Conns"].Health then
							tbl15.Conns.Health:Disconnect()
						end

						if tbl15.Conns["Died"] then
							tbl15.Conns.Died:Disconnect()
						end

						tbl15.Humanoid = humanoid
						tbl15.Health = humanoid.Health
						tbl15.MaxHealth = humanoid.MaxHealth
						tbl15.Alive = tbl15.Health > 0

						tbl15["Conns"].Health = humanoid.HealthChanged:Connect(function(health)
							tbl15.Alive = health > 0
							tbl15.Health = health
						end)

						tbl15["Conns"]["Died"] = humanoid.Died:Connect(function()
							tbl15.Alive = false
						end)
					end }).BindHealth

					tbl15.BindTool = ({ BindTool = function(instance)
						if tbl15.Conns.ToolAdded then
							tbl15.Conns.ToolAdded:Disconnect()
						end

						if tbl15.Conns.ToolRemoved then
							tbl15.Conns.ToolRemoved:Disconnect()
						end

						if tbl15["Children"] then
							for _, instance2 in tbl15.Children do
								if instance2:IsA("Tool") then
									tbl15.CurrentTool = instance2.Name
									break
								end
							end
						end

						tbl15["Conns"].ToolAdded = instance.ChildAdded:Connect(function(child)
							if child:IsA("Tool") then
								tbl15.CurrentTool = child.Name
							end
						end)

						tbl15.Conns.ToolRemoved = instance.ChildRemoved:Connect(function(child)
							if child:IsA("Tool") then
								tbl15.CurrentTool = nil
							end
						end)
					end }).BindTool

					tbl15.BindChildren = ({ BindChildren = function(instance)
						if tbl15.Conns.ChildAdded then
							tbl15.Conns.ChildAdded:Disconnect()
						end

						if tbl15.Conns["ChildRemoved"] then
							tbl15.Conns.ChildRemoved:Disconnect()
						end

						local children = instance:GetChildren()
						tbl15.Children = children

						tbl15.Conns.ChildAdded = instance.ChildAdded:Connect(function(child)
							children[#children + 1] = child
						end)

						tbl15.Conns.ChildRemoved = instance.ChildRemoved:Connect(function(child)
							for i = #children, 1, -1 do
								if children[i] == child then
									remove(children, i)
									break
								end
							end
						end)

						tbl15.BindTool(instance)
					end }).BindChildren

					tbl15.BindFlags = ({ BindFlags = function(humanoid)
						if tbl15.Conns.MoveDir then
							tbl15.Conns.MoveDir:Disconnect()
						end

						if tbl15["Conns"]["StateChange"] then
							tbl15.Conns.StateChange:Disconnect()
						end

						local objects = tbl15.Objects
						tbl15["JumpActive"] = false
						tbl15.WalkActive = false
						tbl15.FallingActive = false
						tbl15.SwimmingActive = false

						objects.WalkFlag.Visible = false
						objects.JumpFlag.Visible = false
						objects["SwimmingFlag"].Visible = false

						tbl15["Conns"]["MoveDir"] = humanoid:GetPropertyChangedSignal("MoveDirection"):Connect(function()
							local flag13 = humanoid.MoveDirection ~= v24

							if flag13 and not tbl15.WalkActive then
								tbl15.WalkActive = true

								if tbl15.JumpActive then
									objects.WalkFlag.LayoutOrder = 2
								else
									objects.WalkFlag.LayoutOrder = 1
									objects.JumpFlag.LayoutOrder = 2
								end

								objects["WalkFlag"].Visible = table_2.Flags.Walking.Enabled
							elseif not flag13 and tbl15.WalkActive then
								tbl15.WalkActive = false
								objects.WalkFlag.Visible = false
							end
						end)

						tbl15.Conns.StateChange = humanoid.StateChanged:Connect(function(old, new)
							if new == Enum.HumanoidStateType.Jumping and not tbl15.JumpActive then
								tbl15.JumpActive = true
								objects.JumpFlag.Visible = table_2.Flags.Jumping.Enabled

								if tbl15.WalkActive then
									objects.JumpFlag.LayoutOrder = 2
								else
									objects.JumpFlag.LayoutOrder = 1
									objects["WalkFlag"].LayoutOrder = 2
								end
							elseif new == Enum.HumanoidStateType.Landed and tbl15.JumpActive then
								tbl15.JumpActive = false
								objects.JumpFlag.Visible = false

								if tbl15.WalkActive then
									objects.WalkFlag.LayoutOrder = 1
								end
							end

							if new == Enum.HumanoidStateType.Swimming and not tbl15["SwimmingActive"] then
								tbl15["SwimmingActive"] = true
								objects.SwimmingFlag.Visible = table_2.Flags.Swimming.Enabled
							elseif new ~= Enum.HumanoidStateType.Swimming and tbl15["SwimmingActive"] then
								tbl15["SwimmingActive"] = false
								objects["SwimmingFlag"].Visible = false
							end
						end)
					end }).BindFlags

					local tbl16 = { OnCharacter = function(character)
						tbl15.Character = character
						tbl15.RootPart = nil
						tbl15.Humanoid = nil
						tbl15.Children = nil
						tbl15.Alive = false
						tbl15.WalkActive = false
						tbl15.JumpActive = false
						tbl15.FallingActive = false
						tbl15.SwimmingActive = false
						if not character or not character.Parent then
							return
						end
						local firstChild = findFirstChild(character, "HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 10)
						local humanoid = findFirstChildOfClass(character, "Humanoid") or character:WaitForChild("Humanoid", 10)
						if not firstChild or not humanoid then
							return
						end

						if not character.Parent then
							return
						end
						tbl15.RootPart = firstChild
						tbl15["Humanoid"] = humanoid
						tbl15.BindChildren(character)
						tbl15.BindHealth(humanoid)
					end }

