			thread5 = task.spawn(function()
				while spiderLilyFarm2 and fn18("SpiderLilyFarm") do
					local children = getChildren()
					local humanoidRootPart = getHumanoidRootPart2()

					if humanoidRootPart and #children > 0 then
						for _, child in ipairs(children) do
							if not spiderLilyFarm2 then
								break
							end
							local boundingBox = child:GetBoundingBox()
							if not boundingBox then
