							end
							humanoidRootPart.CFrame = boundingBox * CFrame.new(0, 3, 0)
							humanoidRootPart.AssemblyLinearVelocity = Vector3.zero
							task.wait(0.5)

							for _, descendant in ipairs(child:GetDescendants()) do
